"""
AlphaCandy Grandmaster: Frontier Campaign Runner (Levels 7,501 to 10,000) - Residual Unrun Batch.
Evaluates the remaining 300 unrun levels (Levels 9,701 to 10,000) on Kaggle 4 vCPUs,
seamlessly combining them with the 2,200 already evaluated levels into the complete
2,500-level benchmark catalog.

Features:
  - 4 Parallel Workers with multiprocessing context isolation
  - Master Weights: 14.4M Spatial Attention Transformer + Dueling DQN Master
  - Depth-2 Tactical Lookahead with Top-5 Candidate Beam Pruning
  - Unified 2,500-level progress output: progress_frontier_7501_10000.json
  - Full Executive Markdown Benchmark Report: FRONTIER_7501_10000_REPORT.md
"""

import os
import sys
import time
import json
import zlib
import base64
import zipfile
import shutil
from typing import Dict, Any, List
from multiprocessing import Pool, cpu_count
import torch

for _p in ["/kaggle/working", "/kaggle/working/candy_crush_pkg", os.getcwd()]:
    if _p not in sys.path:
        sys.path.insert(0, _p)
os.environ["PYTHONPATH"] = f"/kaggle/working:/kaggle/working/candy_crush_pkg:{os.environ.get('PYTHONPATH', '')}"

_WORKER_AGENT = None
_WORKER_LOADER = None
_WORKER_PROCEDURAL_GEN = None

# 2,200 previously evaluated levels (7,501 to 9,700: 1,644 Won, 74.73%)
PRIOR_2200_B64 = ""


def setup_environment() -> tuple:
    print("==================================================================")
    print("  ALPHACANDY GRANDMASTER: FRONTIER RESIDUAL (LEVELS 9,701 - 10,000) ")
    print("==================================================================")

    input_root = "/kaggle/input" if os.path.exists("/kaggle") else "./kaggle_deploy/src"
    work_dir = "/kaggle/working" if os.path.exists("/kaggle") else "/tmp/candy_frontier_75k"
    os.makedirs(work_dir, exist_ok=True)

    src_root = None
    data_json_found = None
    sqlite_found = None

    for root, dirs, files in os.walk(input_root):
        if "candy_crush_pkg.zip" in files and src_root is None:
            zip_path = os.path.join(root, "candy_crush_pkg.zip")
            print(f"[INFO] Extracting {zip_path} into {work_dir}...")
            try:
                with zipfile.ZipFile(zip_path, "r") as zip_ref:
                    zip_ref.extractall(work_dir)
                src_root = work_dir
                print("[INFO] Extraction complete.")
            except Exception as e:
                print(f"[WARN] Failed extracting zip: {e}")

        if "core" in dirs and "models" in dirs and src_root is None:
            src_root = root
            print(f"[INFO] Discovered source tree at: {src_root}")

        if "candycrush_master_levels.json" in files:
            data_json_found = os.path.join(root, "candycrush_master_levels.json")
        if "candycrush_master_levels.sqlite" in files:
            sqlite_found = os.path.join(root, "candycrush_master_levels.sqlite")

    if not src_root:
        candidate_root = "/kaggle/input/candy-crush-grandmaster-rl/candy_crush_pkg"
        if os.path.exists(os.path.join(candidate_root, "core", "king_level_loader.py")):
            src_root = candidate_root
        else:
            src_root = work_dir

    if src_root and os.path.abspath(src_root) != os.path.abspath(work_dir):
        print(f"[INFO] Copying source files from {src_root} to {work_dir}...")
        for item in os.listdir(src_root):
            s_item = os.path.join(src_root, item)
            d_item = os.path.join(work_dir, item)
            if not os.path.exists(d_item):
                try:
                    if os.path.isdir(s_item):
                        shutil.copytree(s_item, d_item)
                    else:
                        shutil.copy2(s_item, d_item)
                except Exception as e:
                    print(f"[WARN] Failed copying {item}: {e}")

    for p in [work_dir, src_root]:
        if p and p not in sys.path:
            sys.path.insert(0, p)

    if data_json_found:
        os.environ["KING_CONFIG_PATH"] = data_json_found
    if sqlite_found:
        os.environ["KING_SQLITE_PATH"] = sqlite_found

    print(f"[INFO] CPU Count: {cpu_count()} | Working Dir: {work_dir}")
    return work_dir, src_root


def init_worker(paths: tuple = None):
    global _WORKER_AGENT, _WORKER_LOADER, _WORKER_PROCEDURAL_GEN
    if paths:
        work_dir, src_root = paths
        for p in [src_root, work_dir]:
            if p and p not in sys.path:
                sys.path.insert(0, p)
        if work_dir and os.path.exists(work_dir):
            try:
                os.chdir(work_dir)
            except Exception:
                pass
    else:
        for p in ["/kaggle/working", "/kaggle/working/candy_crush_pkg", os.getcwd()]:
            if os.path.exists(p) and p not in sys.path:
                sys.path.insert(0, p)

    from core.king_level_loader import KingLevelLoader
    from core.procedural_levels import ProceduralKingGenerator
    from core.reverse_engine import ReverseCandyEngine
    from models.grandmaster_consensus_agent import GrandmasterConsensusAgent

    _WORKER_LOADER = KingLevelLoader()
    _WORKER_PROCEDURAL_GEN = ProceduralKingGenerator()
    engine = ReverseCandyEngine()

    large_ckpt = "checkpoints/alphacandy_large_net_master.pt"
    if not os.path.exists(large_ckpt):
        large_ckpt = "checkpoints/alphacandy_large_net.pt"

    dqn_ckpt = "checkpoints/candy_crush_dueling_dqn_master.pt"
    if not os.path.exists(dqn_ckpt):
        dqn_ckpt = "checkpoints/candy_crush_dueling_dqn.pt"

    _WORKER_AGENT = GrandmasterConsensusAgent(
        large_transformer_ckpt=large_ckpt if os.path.exists(large_ckpt) else None,
        dqn_master_ckpt=dqn_ckpt if os.path.exists(dqn_ckpt) else None,
        search_depth=2,
        top_k_candidates=5,
        engine=engine,
        device="cpu"
    )


def solve_frontier_level_task(args: tuple) -> Dict[str, Any]:
    level_id, max_attempts = args
    global _WORKER_LOADER, _WORKER_PROCEDURAL_GEN, _WORKER_AGENT

    if _WORKER_AGENT is None:
        init_worker()

    t_start = time.time()
    try:
        if level_id <= 10295:
            cfg = _WORKER_LOADER.load_level(level_id)
        else:
            cfg = _WORKER_PROCEDURAL_GEN.generate_level(level_id)
    except Exception as e:
        return {
            "level_id": int(level_id),
            "won": False,
            "attempt": 0,
            "error": f"LoadError: {e}",
            "duration_sec": round(time.time() - t_start, 2)
        }

    initial_seed = (level_id * 10007 + 42) % 1000003
    try:
        res = _WORKER_AGENT.solve_level(cfg, max_attempts=max_attempts, seed=initial_seed)
        won = bool(res.get("won", False))
        att = int(res.get("attempt", 1))
        return {
            "level_id": int(level_id),
            "won": won,
            "attempt": att,
            "winning_seed": (initial_seed + (att - 1) * 313) if won else None,
            "moves_used": int(res.get("moves_used", 0)),
            "moves_limit": int(cfg.moves_limit),
            "moves_remaining": int(res.get("moves_remaining", 0)),
            "final_score": int(res.get("final_score", 0)),
            "objectives_remaining": int(res.get("objectives_remaining", 0)),
            "level_type": cfg.level_type.name,
            "duration_sec": round(float(res.get("duration_sec", time.time() - t_start)), 2),
            "error": None
        }
    except Exception as e_run:
        return {
            "level_id": int(level_id),
            "won": False,
            "attempt": 1,
            "error": str(e_run),
            "duration_sec": round(time.time() - t_start, 2)
        }


def main():
    work_dir, src_root = setup_environment()
    workers = min(4, cpu_count())
    max_attempts = 2

    # Load 2,200 prior evaluated levels (7,501 to 9,700)
    print("[INFO] Decompressing prior 2,200 evaluation results (Levels 7,501 - 9,700)...")
    prior_raw = zlib.decompress(base64.b64decode(PRIOR_2200_B64.encode('ascii'))).decode('utf-8')
    prior_results = json.loads(prior_raw)
    prior_won = sum(1 for x in prior_results if x.get("won"))
    already_evaluated_ids = set(x["level_id"] for x in prior_results)

    print(f"[INFO] Prior Evaluated: {len(prior_results)} levels | Prior Solved: {prior_won} ({prior_won/len(prior_results)*100:.2f}%)")

    # Target the unrun levels: 9,701 to 10,000 (300 levels)
    unrun_levels = [lvl for lvl in range(7501, 10001) if lvl not in already_evaluated_ids]
    unrun_levels.sort()
    total_unrun = len(unrun_levels)
    task_args = [(lvl, max_attempts) for lvl in unrun_levels]

    print(f"[INFO] Unrun Target Identified: {total_unrun} levels ({min(unrun_levels)} to {max(unrun_levels)})")
    print(f"[INFO] Workers={workers} | Max Attempts={max_attempts} | Lookahead Depth=2")

    new_results = []
    new_won = 0
    t_start = time.time()

    with Pool(processes=workers, initializer=init_worker, initargs=((work_dir, src_root),)) as pool:
        for idx, res in enumerate(pool.imap(solve_frontier_level_task, task_args, chunksize=4), 1):
            new_results.append(res)
            if res["won"]:
                new_won += 1

            if idx % 10 == 0 or idx == total_unrun:
                elapsed = time.time() - t_start
                rate = (new_won / idx) * 100.0
                speed = idx / elapsed
                remain = (total_unrun - idx) / speed if speed > 0 else 0
                print(f"[{idx:3d}/{total_unrun}] Residual Solved: {new_won:3d} ({rate:5.1f}%) | "
                      f"Speed: {speed:4.1f} lvl/s | Elapsed: {elapsed/60.0:4.1f}m | ETA: {remain/60.0:4.1f}m")

                # Atomic checkpoint of unified 2,500 levels
                combined_checkpoint = prior_results + new_results
                out_path = os.path.join(work_dir, "progress_frontier_7501_10000.json")
                with open(out_path + ".tmp", "w") as f:
                    json.dump(combined_checkpoint, f, indent=2)
                os.replace(out_path + ".tmp", out_path)

    elapsed_total = time.time() - t_start
    combined_all = prior_results + new_results
    total_catalog = len(combined_all)
    total_won = sum(1 for x in combined_all if x.get("won"))
    final_rate = (total_won / total_catalog) * 100.0

    print(f"\n[INFO] Residual Batch Finished in {elapsed_total/60.0:.1f}m. New Wins: {new_won}/{total_unrun} ({new_won/total_unrun*100:.2f}%)")
    print(f"[INFO] Full Catalog 7,501 - 10,000 Complete: {total_won}/{total_catalog} ({final_rate:.2f}%)")

    # Save final combined JSON
    final_json_path = os.path.join(work_dir, "progress_frontier_7501_10000.json")
    with open(final_json_path, "w") as f:
        json.dump(combined_all, f, indent=2)

    # Breakdown by game mode for full 2,500 levels
    modes = {}
    for r in combined_all:
        lt = r.get("level_type", "UNKNOWN")
        if lt not in modes:
            modes[lt] = {"total": 0, "won": 0}
        modes[lt]["total"] += 1
        if r.get("won"):
            modes[lt]["won"] += 1

    mode_table_lines = ["| Game Mode | Evaluated | Won | Win Rate (%) |", "| :--- | :---: | :---: | :---: |"]
    for m, d in sorted(modes.items()):
        m_rate = (d["won"] / d["total"]) * 100.0 if d["total"] > 0 else 0
        mode_table_lines.append(f"| **{m}** | {d['total']} | {d['won']} | **{m_rate:.2f}%** |")
    mode_table = "\n".join(mode_table_lines)

    report = f"""# 🚀 AlphaCandy Frontier Benchmark: Levels 7,501 to 10,000 (Complete 2,500-Level Catalog)

- **Total Levels Evaluated**: {total_catalog:,} (Levels 7,501 to 10,000)
- **Total Levels Conquered**: {total_won:,} / {total_catalog:,} (**{final_rate:.2f}%**)
- **Prior Batch**: 2,200 levels (1,644 won, 74.73%)
- **Residual Batch**: {total_unrun} levels ({new_won} won, {new_won/total_unrun*100:.2f}%)
- **Model Architecture**: Grandmaster Consensus Agent (14.4M Spatial Attention Transformer + Double Dueling DQN Master)
- **Search Parameters**: Depth-2 Tactical Lookahead, Top-5 Candidate Beam Pruning, Max Attempts=2

## 📊 Breakdown by Game Mode (Full 2,500 Levels)
{mode_table}
"""
    with open(os.path.join(work_dir, "FRONTIER_7501_10000_REPORT.md"), "w") as f:
        f.write(report)

    print("="*70)
    print(f"   FRONTIER BENCHMARK 7,501 - 10,000 COMPLETE: {total_won}/{total_catalog} ({final_rate:.2f}%)")
    print("="*70 + "\n")


if __name__ == "__main__":
    main()
